def build_families(components: list[dict[str, Any]], base: types.ModuleType) -> tuple[list[dict[str, Any]], dict[str, list[str]]]:
    adjacency: dict[int, set[int]] = defaultdict(set)
    for i, left in enumerate(components):
        for j in range(i + 1, len(components)):
            right = components[j]
            if left['year'] == right['year']:
                continue
            if centroid_distance(left['centroid'], right['centroid'], base) <= FAMILY_LINK_RADIUS:
                adjacency[i].add(j)
                adjacency[j].add(i)
    seen: set[int] = set()
    families: list[dict[str, Any]] = []
    for start in range(len(components)):
        if start in seen or start not in adjacency:
            continue
        queue = deque([start])
        seen.add(start)
        members: list[int] = []
        while queue:
            idx = queue.popleft()
            members.append(idx)
            for nxt in adjacency[idx]:
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
        family_components = [components[i] for i in members]
        years = sorted({int(c['year']) for c in family_components})
        if len(years) < MIN_FAMILY_YEARS:
            continue
        event_ids = sorted(set().union(*(set(c['event_ids']) for c in family_components)))
        component_ids = sorted((c['component_id'] for c in family_components))
        stable_id = 'G' + hashlib.sha256('|'.join(component_ids).encode()).hexdigest()[:12]
        year_strengths = {str(year): float(max((c['component_strength'] for c in family_components if int(c['year']) == year))) for year in years}
        family = {'family_id': stable_id, 'years': years, 'year_count': len(years), 'component_ids': component_ids, 'component_count': len(family_components), 'event_ids': event_ids, 'event_count': len(event_ids), 'quartet_count': int(sum((c['quartet_count'] for c in family_components))), 'anchor_count': int(sum((c['anchor_count'] for c in family_components))), 'best_score': float(max((c['best_score'] for c in family_components))), 'year_strengths': year_strengths, 'centroids': {str(c['year']): c['centroid'] for c in family_components}, 'ranks': {}}
        family['ranking_scores'] = family_scores(family)
        families.append(family)
    rankings = rank_families(families)
    return (families, rankings)

