def component_records(year: int, passing: list[dict[str, Any]], event_lookup: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    adjacency: dict[str, set[str]] = defaultdict(set)
    quartet_by_node: dict[str, set[int]] = defaultdict(set)
    for q_index, record in enumerate(passing):
        ids = record['quartet_ids']
        for event_id in ids:
            quartet_by_node[event_id].add(q_index)
        for i in range(4):
            for j in range(i + 1, 4):
                adjacency[ids[i]].add(ids[j])
                adjacency[ids[j]].add(ids[i])
    seen: set[str] = set()
    components: list[dict[str, Any]] = []
    for start in sorted(adjacency):
        if start in seen:
            continue
        queue = deque([start])
        seen.add(start)
        nodes: list[str] = []
        while queue:
            node = queue.popleft()
            nodes.append(node)
            for nxt in adjacency[node]:
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
        quartet_indices = sorted(set().union(*(quartet_by_node[node] for node in nodes)))
        if len(nodes) < MIN_COMPONENT_EVENTS or len(quartet_indices) < MIN_COMPONENT_QUARTETS:
            continue
        events = [event_lookup[node] for node in nodes]
        sol_center = circular_mean_deg((float(e['sol']) for e in events))
        lon_center = circular_mean_deg((float(e['sun_lon']) for e in events))
        strengths = [float(passing[i]['bin_strength']) for i in quartet_indices]
        component_strength = float(sum(strengths) / math.sqrt(len(strengths)))
        component = {'year': year, 'event_ids': sorted(nodes), 'event_count': len(nodes), 'quartet_count': len(quartet_indices), 'anchor_count': int(sum((passing[i]['anchor_count'] for i in quartet_indices))), 'best_score': float(max((passing[i]['score'] for i in quartet_indices))), 'median_score': float(np.median([passing[i]['score'] for i in quartet_indices])), 'component_strength': component_strength, 'centroid': {'sol': sol_center, 'sun_lon': lon_center, 'ecl_lat': float(np.median([float(e['ecl_lat']) for e in events])), 'vg': float(np.median([float(e['vg']) for e in events]))}, 'solar_span_deg': float(max((float(e['sol']) for e in events)) - min((float(e['sol']) for e in events)))}
        components.append(component)
    components.sort(key=lambda x: (-x['event_count'], -x['quartet_count'], -x['component_strength'], x['centroid']['sol']))
    for index, component in enumerate(components, 1):
        component['component_id'] = f'{year}-C{index:04d}'
    return components

