def develop_wrapper(hidden_labels: dict[str, str], panel_results: dict[str, dict[str, Any]]) -> dict[str, Any]:
    development = panel_results['development']['evaluation']
    validation = panel_results['validation']['evaluation']

    def selection_key(variant: str) -> tuple[float, ...]:
        m = development['metrics'][variant]
        return (float(m['recovered_at_100']), float(m['recovered_at_500']), float(m['mrr']), float(m['top100_dominant_precision']))
    selected_variant = max(RANKING_VARIANTS, key=lambda variant: (selection_key(variant), -RANKING_VARIANTS.index(variant)))
    comparisons: dict[str, dict[str, float]] = {}
    for panel_name, panel in (('development', development), ('validation', validation)):
        baseline = panel['metrics']['persistence']
        selected = panel['metrics'][selected_variant]
        comparisons[panel_name] = {'recovered_at_100_delta': selected['recovered_at_100'] - baseline['recovered_at_100'], 'recovered_at_500_delta': selected['recovered_at_500'] - baseline['recovered_at_500'], 'mrr_delta': selected['mrr'] - baseline['mrr'], 'top100_precision_delta': selected['top100_dominant_precision'] - baseline['top100_dominant_precision']}
    passes = bool(selected_variant != 'persistence' and comparisons['development']['recovered_at_100_delta'] >= 1 and (comparisons['validation']['recovered_at_100_delta'] >= 0) and (comparisons['validation']['recovered_at_500_delta'] >= 0) and (comparisons['validation']['mrr_delta'] > 0.0) and (comparisons['validation']['top100_precision_delta'] >= -0.1))
    return {'selected_variant': selected_variant, 'selection_used_years': development['years'], 'untouched_validation_years': validation['years'], 'panel_evaluations': {'development': development, 'validation': validation}, 'improvement_over_persistence': comparisons, 'verdict': 'PASS_SUPPORT_NORMALIZED_WRAPPER_DEVELOPMENT' if passes else 'FAIL_SUPPORT_NORMALIZED_WRAPPER_DEVELOPMENT'}

