def evaluate_panel(hidden_labels: dict[str, str], families: list[dict[str, Any]], rankings: dict[str, list[str]], panel_years: tuple[int, ...]) -> dict[str, Any]:
    label_year_counts: dict[str, Counter[int]] = defaultdict(Counter)
    for event_id, label in hidden_labels.items():
        year = int(str(event_id)[:4])
        if year in panel_years and label != 'SPORADIC':
            label_year_counts[label][year] += 1
    eligible = {label: counts for label, counts in label_year_counts.items() if sum(counts.values()) >= 8 and all((counts.get(year, 0) >= 4 for year in panel_years))}
    if len(eligible) < 8:
        raise RuntimeError(f'insufficient eligible known showers in years {panel_years}: {len(eligible)}')
    family_by_id = {f['family_id']: f for f in families}
    family_label_stats: dict[str, dict[str, Any]] = {}
    for family in families:
        counts = Counter((hidden_labels.get(event_id, 'SPORADIC') for event_id in family['event_ids']))
        counts.pop('SPORADIC', None)
        label, count = counts.most_common(1)[0] if counts else (None, 0)
        family_label_stats[family['family_id']] = {'dominant_label': label, 'dominant_count': int(count), 'dominant_precision': float(count / family['event_count']) if family['event_count'] else 0.0}
    best_family_for_label: dict[str, dict[str, Any] | None] = {}
    for label, year_counts in eligible.items():
        total = int(sum(year_counts.values()))
        candidates: list[tuple[float, float, int, str, int]] = []
        for family in families:
            overlap = sum((hidden_labels.get(event_id) == label for event_id in family['event_ids']))
            if overlap < 4:
                continue
            precision = overlap / family['event_count']
            recall = overlap / total
            f1 = 2.0 * precision * recall / (precision + recall) if precision + recall else 0.0
            candidates.append((f1, precision, overlap, family['family_id'], total))
        if not candidates:
            best_family_for_label[label] = None
            continue
        f1, precision, overlap, family_id, total = max(candidates, key=lambda x: (x[0], x[1], x[2], x[3]))
        best_family_for_label[label] = {'family_id': family_id, 'overlap': int(overlap), 'precision': float(precision), 'recall': float(overlap / total), 'f1': float(f1), 'total': total}
    metrics: dict[str, dict[str, Any]] = {}
    for variant in RANKING_VARIANTS:
        rank_map = {family_id: rank for rank, family_id in enumerate(rankings[variant], 1)}
        top100 = [family_by_id[fid] for fid in rankings[variant][:100]]
        top100_precision = float(np.mean([family_label_stats[f['family_id']]['dominant_precision'] for f in top100])) if top100 else 0.0
        ranks: list[int] = []
        f1s: list[float] = []
        recovered100 = 0
        recovered500 = 0
        qualified = 0
        per_label: list[dict[str, Any]] = []
        for label in sorted(eligible):
            match = best_family_for_label[label]
            if match is None:
                per_label.append({'label': label, 'rank': None, 'qualified': False})
                continue
            rank = rank_map[match['family_id']]
            is_qualified = bool(match['precision'] >= 0.5 and match['overlap'] >= 4)
            if is_qualified:
                qualified += 1
                ranks.append(rank)
                f1s.append(match['f1'])
                recovered100 += int(rank <= 100)
                recovered500 += int(rank <= 500)
            per_label.append({'label': label, 'rank': rank, 'qualified': is_qualified, **match})
        metrics[variant] = {'eligible_labels': len(eligible), 'qualified_matches': qualified, 'recovered_at_100': recovered100, 'recovered_at_500': recovered500, 'mrr': float(np.mean([1.0 / rank for rank in ranks])) if ranks else 0.0, 'median_rank': float(np.median(ranks)) if ranks else None, 'macro_f1': float(np.mean(f1s)) if f1s else 0.0, 'top100_dominant_precision': top100_precision, 'per_label': per_label}
    return {'years': list(panel_years), 'eligible_label_count': len(eligible), 'eligible_label_year_counts': {label: {str(year): int(counts.get(year, 0)) for year in panel_years} for label, counts in sorted(eligible.items())}, 'metrics': metrics}

