def load_sources(args: argparse.Namespace) -> tuple[types.ModuleType, types.ModuleType, types.ModuleType]:
    candidate = load_module('orbittrace_blind_candidate', decode_payload(args.candidate_payload), EXPECTED_CANDIDATE_SHA)
    baseline = load_module('orbittrace_blind_baseline', decode_payload(args.baseline_payload), EXPECTED_BASELINE_SHA)
    scorer = load_module('orbittrace_blind_scorer', decode_parts(args.scorer_parts, ['part00.b64', 'part01.b64', 'part02.b64', 'part03.b64']), EXPECTED_SCORER_SHA)
    frozen = {'candidate_scale': getattr(candidate, 'CANDIDATE_SCALE', None), 'episode_size': getattr(baseline, 'EPISODE_SIZE', None), 'window': getattr(baseline, 'WINDOW', None), 'calibration': getattr(scorer, 'CALIBRATION_NEGATIVES_PER_BIN', None), 'bin_width': getattr(scorer, 'MONDRIAN_BIN_WIDTH_DEG', None)}
    expected = {'candidate_scale': 4.0, 'episode_size': 128, 'window': 10.0, 'calibration': 128, 'bin_width': 10.0}
    if frozen != expected:
        raise RuntimeError(f'frozen constants mismatch: {frozen}')
    return (candidate, baseline, scorer)

