def quartet_score(events: list[dict[str, Any]], base: types.ModuleType) -> float:
    distance = np.empty((4, 4), dtype=np.float64)
    for i, anchor in enumerate(events):
        distance[i] = exact_anchor_distances(anchor, events, base)
    np.fill_diagonal(distance, 0.0)
    return -float(np.max(distance))

